const assertMount = (mount) => {
  if (typeof mount !== "function") throw new TypeError("An experience mount function is required.")
  return mount
}

export const createExperienceController = ({ root, mount, options = {} }) => {
  let teardown = null
  let active = false

  const start = async () => {
    if (active) return controller
    const element = typeof root === "string" ? document.querySelector(root) : root
    if (!element) throw new Error(`Experience root was not found: ${String(root)}`)
    const result = await assertMount(mount)(element, options)
    teardown = typeof result === "function" ? result : result?.destroy ?? null
    active = true
    return controller
  }

  const stop = () => {
    if (!active) return
    teardown?.()
    teardown = null
    active = false
  }

  const controller = Object.freeze({ start, stop, restart: async () => { stop(); return start() }, get active() { return active } })
  return controller
}

export const mountExperience = async (definition) => {
  const controller = createExperienceController(definition)
  await controller.start()
  return controller.stop
}

export const createPageExperienceController = (definitions = []) => {
  let controllers = []
  const start = async () => {
    if (controllers.length) return pageController
    controllers = definitions.flatMap((definition) => {
      const roots = typeof definition.root === "string" ? [...document.querySelectorAll(definition.root)] : [definition.root].filter(Boolean)
      return roots.map((root) => createExperienceController({ ...definition, root }))
    })
    await Promise.all(controllers.map((controller) => controller.start()))
    return pageController
  }
  const stop = () => {
    controllers.forEach((controller) => controller.stop())
    controllers = []
  }
  const pageController = Object.freeze({ start, stop, restart: async () => { stop(); return start() }, get active() { return controllers.some((controller) => controller.active) } })
  return pageController
}

